function add(a: number, b: number): number {
  return a + b;
}

const double = (n: number) => n * 2;

console.log(add(2, 3), double(21));
add(1);

function greet(name: string, greeting = "Hello", punctuation?: string): string {
  return `${greeting}, ${name}${punctuation ?? "!"}`;
}

function sum(...values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

console.log(greet("Ada"));
console.log(greet("Ada", "Hi", "?"));
console.log(sum(1, 2, 3, 4));

type Formatter = (value: number) => string;

function formatAll(values: number[], format: Formatter): string[] {
  return values.map(format);
}

const euros: Formatter = (value) => `${value.toFixed(2)} EUR`;

console.log(formatAll([1.5, 20], euros));
console.log(formatAll([3], (value) => value * 2));

function logLine(message: string): void {
  console.log(`> ${message}`);
}

function fail(reason: string): never {
  throw new Error(reason);
}

function parsePort(input: string): number {
  const port = Number(input);
  if (Number.isNaN(port)) {
    fail(`Not a port: ${input}`);
  }
  return port;
}

logLine(`port ${parsePort("8080")}`);
logLine(`port ${parsePort("abc")}`);
